import type { Scene, SceneNode } from '@graphlearning/flow'

// Every code and terminal string below was generated by running it (CPython 3.13, x86-64);
// the scripts are in demos/how-python-runs/. Bytecode, ids and timings are version- and run-specific.

const SOURCE = "price = 9.5\nqty = 2\ntotal = price * qty\nprint(total)"
const TOKENS = "3,0-3,5: NAME 'total'\n3,6-3,7: OP '='\n3,8-3,13: NAME 'price'\n3,14-3,15: OP '*'\n3,16-3,19: NAME 'qty'"
const AST = "Assign(\n  targets=[\n    Name(id='total', ctx=Store())],\n  value=BinOp(\n    left=Name(id='price', ctx=Load()),\n    op=Mult(),\n    right=Name(id='qty', ctx=Load())))"
const BYTECODE = "  3           LOAD_NAME                0 (price)\n              LOAD_NAME                1 (qty)\n              BINARY_OP                5 (*)\n              STORE_NAME               2 (total)"
const RUN = "$ python line_total.py\n19.0"

const stage = (id: string, badge: string, label: string, sub: string, pattern: SceneNode['pattern'], child: SceneNode): SceneNode =>
  ({ id, badge, label, sub, pattern, icon: 'none', children: [child] })

export const runPipeline: Scene = {
  id: 'run-pipeline',
  padding: 0.04,
  header: 'band',
  nodes: [
    {
      id: 'front',
      label: 'Front end',
      bare: true,
      flow: 'LR',
      align: 'start',
      children: [
        stage('read', '1', 'Read the source', 'a text file, nothing more', 'network', { id: 'source', kind: 'code', filename: 'line_total.py', hug: true, minCols: 26, highlight: [3], pattern: 'network', label: SOURCE }),
        stage('tokenize', '2', 'Tokenize', 'line 3 split into words', 'network', { id: 'tokens', kind: 'code', filename: 'python -m tokenize', hug: true, label: TOKENS }),
        stage('parse', '3', 'Parse', 'the syntax tree of line 3', 'network', { id: 'ast', kind: 'code', filename: 'ast.dump', hug: true, label: AST }),
      ],
      edges: [
        { source: 'read', target: 'tokenize' },
        { source: 'tokenize', target: 'parse' },
      ],
    },
    {
      id: 'back',
      label: 'Back end',
      bare: true,
      flow: 'RL',
      align: 'start',
      children: [
        stage('compile', '4', 'Compile', 'line 3 as bytecode', 'service', { id: 'bytecode', kind: 'code', filename: 'python -m dis', hug: true, label: BYTECODE }),
        stage('execute', '5', 'Execute', 'the virtual machine', 'service', {
          id: 'loop', kind: 'list', icon: 'repeat', label: 'The evaluation loop', pattern: 'service',
          items: ['Fetch the next instruction', 'Do it: push, pop, compute', 'Repeat until the code ends'],
        }),
        stage('output', '6', 'Output', 'what you see', 'storage', { id: 'run', kind: 'terminal', filename: 'Terminal', label: RUN }),
      ],
      edges: [
        { source: 'compile', target: 'execute' },
        { source: 'execute', target: 'output' },
      ],
    },
  ],
  edges: [{ source: 'parse', target: 'compile', dir: 'TB' }],
}
